ANNOTATIONS = [
    (43, 'before', '''把 Span 类型与 isBetaTracingEnabled / LLMRequestNewContext 重新导出，方便上层从本模块统一 import，不必直接依赖 OpenTelemetry 或 beta 子模块。'''),
    (47, 'before', '''API 调用的消息类型：用户消息或助手消息，喂给 LLM 请求的 span 当上下文。'''),
    (49, 'before', '''span 类型枚举：interaction（一次用户交互的根 span）、llm_request（模型请求）、tool（工具调用）、tool.blocked_on_user（等用户批权限）、tool.execution（工具执行）、hook（钩子执行）。'''),
    (57, 'before', '''单个 span 的上下文：持有 Span 对象、起始时间、属性表、是否已结束、以及对应的 Perfetto span ID。'''),
    (69, 'before', '''用两个 AsyncLocalStorage 分别持有「当前 interaction」与「当前 tool」的 SpanContext：ALS 直接存强引用，所以 activeSpans 可以用 WeakRef——一旦 ALS 被清空（enterWith(undefined)）且别处不再持有，GC 就能回收，WeakRef 随之失效。'''),
    (71, 'before', '''activeSpans：spanId 到 SpanContext 弱引用的全局表，用于按 ID 找回尚未结束的 span。'''),
    (75, 'before', '''strongSpans：那些「不存进 ALS」的 span（llm_request / blocked_on_user / tool.execution / hook）需要强引用，否则在对应的 end* 函数取回之前可能被 GC 收走。'''),
    (76, 'before', '''interaction 序列号：每次开 interaction span 自增，作为属性记进 span，便于排序与关联。'''),
    (79, 'before', '''span 的生存时间上限：30 分钟。超过这个时限的孤儿 span（没正常结束的）在清理间隔里被强制结束并移除。'''),
    (81, 'before', '''取一个 span 的 spanId（OpenTelemetry 上下文里的 ID），作为本模块内部查表的键。'''),
    (100, 'before', '''惰性启动一个后台清理间隔：正常结束会立即删 span，这个间隔只是「安全网」——兜住那些从没被结束的孤儿 span（如中断的流、查询中途未捕获的异常），否则它们会在 activeSpans 里无限堆积、拽住 Span 对象与 OTel 上下文链。首次开 interaction span 时才启动（不在模块加载时），以避开「顶层副作用」lint 并避免从不建 span 的进程空跑定时器；unref 让定时器不阻止进程退出。'''),
    (126, 'before', '''判断「增强遥测」是否开启：优先级是「环境变量覆盖 > ant 构建 > GrowthBook 开关」。特性开关 ENHANCED_TELEMETRY_BETA 是总闸；开启后读两个环境变量（真则开、明确假则关），都没设就回落到「USER_TYPE 为 ant 或 GrowthBook 命中」。'''),
    (148, 'before', '''判断「是否有任何追踪开启」：增强遥测或 beta 追踪任一为真即可。'''),
    (152, 'before', '''取 tracer：统一用固定名字与版本号 com.anthropic.claude_code.tracing / 1.0.0。'''),
    (156, 'before', '''构造一个 span 的属性表：先取全局遥测基础属性，再补 span.type 与调用方给的自定义属性。'''),
    (176, 'before', '''开一个 interaction span，包裹「用户请求 → Claude 响应」整轮：无论 OTel 是否开启都会先开 Perfetto span；若任何追踪都没开，只保留 Perfetto 的哑 span 并登记进 activeSpans；否则建真正的 interaction span，记 user_prompt（开了日志才记原文，否则记 REDACTED）、prompt 长度、交互序列号，再挂上 beta 的实验属性，最后用 ALS 把上下文设为当前 interaction。'''),
    (237, 'before', '''结束当前 interaction span：从 ALS 取上下文，幂等（已结束直接返回）；先结束 Perfetto span，再补 duration_ms、结束 OTel span，并 enterWith(undefined) 清空存储，使此后的异步续体（定时器 / promise 回调 / IO）不再继承已结束 span 的引用。'''),
    (274, 'before', '''开一个 LLM 请求 span：同样先开 Perfetto span；OTel 关闭时只留哑 span 并登记（同时存强引用）；否则以 interaction span 为父建子 span，记 model、上下文来源（interaction 还是 standalone）、速度档（fast / normal），再挂 query_source 与 beta 的实验属性。'''),
    (353, 'before', '''结束一个 LLM 请求 span 并附响应元数据：强烈建议传具体 span（并行多个 LLM 请求时，不传会错误地落到 activeSpans 里「最后一个」llm_request span，造成响应张冠李戴）；按 span 找回上下文，补时长、token 数、成功与否、状态码、错误、首 token 时延等，再结束 span 并清理两个表。'''),
    (466, 'before', '''开一个工具调用 span：以 interaction span 为父，记 tool_name 与调用方属性，挂 beta 的工具输入属性，用 ALS 设为当前 tool 上下文。'''),
    (526, 'before', '''开一个「工具卡在等用户批权限」的 span：父是 tool 上下文，类型 tool.blocked_on_user，记进 activeSpans 并加强引用（不进 ALS）。'''),
    (577, 'before', '''结束「卡在等用户」的 span：从 activeSpans 里按类型找最后一个 blocked_on_user span，补 decision / source 与时长后结束并清理。'''),
    (626, 'before', '''开一个「工具执行」span：父是 tool 上下文，类型 tool.execution，加强引用（不进 ALS）。'''),
    (657, 'before', '''结束「工具执行」span：同样按类型找回最后一个 tool.execution span，补 success / error 与时长后结束并清理。'''),
    (691, 'before', '''结束当前工具调用 span：从 tool ALS 取上下文，先结束 Perfetto span，再补时长、工具结果（beta 属性，含 result_tokens）后结束；最后清空 tool 上下文，防止后续异步工作拽住已结束的 span 引用。'''),
    (738, 'before', '''判断「是否记录工具内容」：仅当环境变量 OTEL_LOG_TOOL_CONTENT 为真时才记。'''),
    (747, 'before', '''给当前 span 加一条「工具内容」事件：任何追踪没开或没开内容日志就直接返回；对超长的字符串属性做截断（truncateContent），并附上「是否截断」与「原长」两个标记，便于排障。'''),
    (778, 'before', '''取「当前 span」：优先 tool 上下文的 span，其次 interaction 上下文的 span，都没有返回 null。'''),
    (788, 'before', '''在一个 span 内执行一段异步函数 executeInSpan：以 tool / interaction 上下文为父建 span，执行 fn，无论成功失败都结束 span 并清理（失败会把异常记进 span 再抛出）。'''),
    (844, 'before', '''开一个钩子执行 span：仅在 beta 追踪开启时建真正的 span（否则返回哑 span）；记 hook_event / hook_name / num_hooks / hook_definitions，以 tool 或 interaction 上下文为父。'''),
    (887, 'before', '''结束一个钩子 span 并附结果元数据：仅 beta 追踪开启时做事；按 span 找回上下文，补时长与 num_success / num_blocking / num_non_blocking_error / num_cancelled 后结束并清理两表。'''),
]
